{"styleObjects":{},"customStyles":".headerFacilityLabel {
 font-size: 0.875rem;
 font-weight: 400;
 color: #181818;
 line-height: 1.25;
 margin-bottom: 0.35rem;
}

.facilityName {
 font-size: 1.1rem;
 font-weight: 700;
 line-height: 1;
 color: #032d60;
 margin: 0;
 padding: 0;
}

.detailLabel {
 font-size: 0.8525rem;
 font-weight: 649;
 color: #181818;
 line-height: 1.4;
}

.detailValue {
 font-size: 0.8125rem;
 font-weight: 400;
 color: #181818;
 line-height: 1.4;
}

.block-header-heading {
 width: 100% !important;
 background-color: #f3f3f3 !important;
 height: 38px !important;
}

.slds-form-element__label {
 padding-bottom: 10px;
 color: #7E8C8D;
 font-size: 13px;
}

.field-value {
 margin-top: 1px;
 display: block;
}

.field-display {
 height: 50px;
 padding-left: 10px;
 padding-top: 5px;
 margin-bottom: 5px;
}

.blockSlot {
 padding-left: 4px;
 padding-top: 4px;
 padding-bottom: 3px;
}

.addressLink {
 font-size: 0.8125rem;
 font-weight: 400;
 color: #014486;
 text-decoration: none;
 line-height: 1.4;
 word-break: break-word;
 cursor: pointer;
}

.addressLink:hover {
 text-decoration: underline;
 color: #032d60;
}

.water-advisory-banner {
 display: flex;
 align-items: center;
 background: #fdb913;
 color: #111;
 padding: 12px 24px;
 width: 100%;
 border: none;
 box-shadow: none;
}

.wateradvisoryrow {
 display: flex !important;
 align-items: center;
}

.WaterAdvisoryBannerBlockIconContainer {
 width: 20px !important;
 min-width: 20px !important;
 flex: 0 0 20px !important;
 display: flex;
 align-items: center;
 justify-content: center;
 margin-right: 10px;
 padding: 0 !important;
 align-self: center;
}

.WaterAdvisoryBannerBlockWarningIcon {
 width: 16px !important;
 height: 16px !important;
 fill: #000 !important;
 display: block;
 margin: auto;
}

.water-advisory-content {
 display: flex;
 flex-direction: column;
 flex: 1;
 padding: 0 !important;
 margin: 0 !important;
}

.water-advisory-title {
 font-weight: 700;
 font-size: 14px;
 line-height: 1.25;
 margin: 0;
 color: #111;
}

.water-advisory-reason {
 font-size: 13px;
 line-height: 1.25;
 margin-top: 2px;
 color: #111;
}

/* Inspection Results table header */
.inspection-results-table thead th {
 background-color: #f3f3f3 !important;
 font-weight: 700 !important;
 color: #444 !important;
 border-bottom: 1px solid #d8dde6 !important;
 padding-top: 10px;
 padding-bottom: 10px;
}

/* Optional - row separation */
.inspection-results-table tbody td {
 border-bottom: 1px solid #ecebea;
}"}
